
public class VolumeofEarth {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int radius= 6387;
		double  volume= (4.0/3.0)*3.14 * Math.pow(radius,3);
		double miles =volume * 0.6213711922;
		System.out.println(" The volume of earth in cubic centimeters is :"+ volume +" and cubic miles is :" + miles);  
		

	}

}
